DO $associate$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['imports','mappings','metric_versions','evidence','hypotheses','analytic_plans','analytic_results','report_drafts','report_versions','comments','followups','experiment_candidates','browser_plans','target_grants','test_approvals','evidence_artifacts','integration_captures','model_proposals'] LOOP EXECUTE format('UPDATE faultline.idempotency d SET case_id=r.case_id FROM faultline.%I r WHERE d.workspace_id=r.workspace_id AND d.case_id IS NULL AND d.result->>''id''=r.id::text',t);END LOOP;END $associate$;
